var t=`0641-asida-sudanese-style`;var n=`world-0641`;var s=`SD`;var r=`northern-africa`;var a=8;var o=44;var g={en:`Asida Sudanese Style`,ua:`Асіда по-суданськи`};var l={en:`Asida Sudanese Style is a Sudan classic prepared with sorghum flour, plain yogurt. A measured home-style version, with ingredients assigned to the cooking steps where they are used.`,ua:`Асіда по-суданськи, страва кухні країни Судан зі складниками: соргове борошно, натуральний йогурт. Домашній рецепт із кількостями, прив’язаними до відповідних етапів приготування.`};var u=[{en:`Cook the listed ingredients in simmering water for about 9 minutes until tender; drain well if necessary.`,ua:`Варіть зазначені складники у воді приблизно 9 хвилин до м’якості; за потреби добре злийте воду.`,t:[`boiling`],m:9,i:[[`water`,850,`ml`],[`table-salt`,4,`g`]]},{en:`Slowly stir the grains into the simmering liquid; cook over low heat for about 23 minutes, stirring to prevent sticking.`,ua:`Повільно всипте крупу в гарячу рідину; варіть на слабкому вогні приблизно 23 хвилин, помішуючи, щоб не пристала до дна.`,t:[`absorption-cooking`],m:23,i:[[`sorghum-flour`,300,`g`],[`unsalted-butter`,35,`g`]]},{en:`Roll or press the prepared dough evenly into the desired thickness and shape.`,ua:`Розкачайте або розпластайте підготовлене тісто рівномірним шаром потрібної товщини та форми.`,t:[`pressing`,`rolling-out-dough`],m:8,i:[]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:4,i:[[`honey`,70,`g`],[`plain-yogurt`,170,`g`]]}];var d={slug:t,id:n,country:`SD`,region:r,servings:8,minutes:44,title:g,text:l,steps:u};export{s as country,d as default,n as id,o as minutes,r as region,a as servings,t as slug,u as steps,l as text,g as title};